public static boolean czyPo(String a, String b) {
    return a.compareTo(b) == 1;
}

public static void main(String[] args) {
    System.out.println(czyPo("abd", "abc"));
    System.out.println(czyPo("bank", "Zupa"));
    System.out.println(czyPo("Ala", "ala"));
}

public static String pierwsze(String a, String b) {
    if (a.compareTo(b) > 0) {
        return a;
    }
    return b;
}

public static void main(String[] args) {
    System.out.println(pierwsze("Ola", "Adam"));
    System.out.println(pierwsze("bank", "Zupa"));
    System.out.println(pierwsze("kot", "kotek"));
}

